let currentLocale = DEFAULT_LOCALE;

export function normalizeLocale(value) {
  const normalized = String(value || '').trim();
  if (normalized === 'zh' || normalized.toLowerCase().startsWith('zh-')) return 'zh-CN';
  if (normalized === 'en' || normalized.toLowerCase().startsWith('en-')) return 'en';
  return SUPPORTED_LOCALES.includes(normalized) ? normalized : DEFAULT_LOCALE;
}

export function setLocale(locale) {
  currentLocale = normalizeLocale(locale);
  return currentLocale;
}

export function getLocale() {
  return currentLocale;
}

export function t(key, variables = {}) {
  const template = TRANSLATIONS[currentLocale]?.[key] ?? TRANSLATIONS[FALLBACK_LOCALE]?.[key] ?? key;
  return String(template).replace(/\{(\w+)\}/g, (match, name) => Object.prototype.hasOwnProperty.call(variables, name) ? String(variables[name]) : match);
}

export function hasTranslation(key, locale = currentLocale) {
  return Boolean(TRANSLATIONS[normalizeLocale(locale)]?.[key] || TRANSLATIONS[FALLBACK_LOCALE]?.[key]);
}

export function applyTranslations(root = document) {
  root.documentElement?.setAttribute('lang', currentLocale);
  root.querySelectorAll?.('[data-i18n]').forEach((element) => { element.textContent = t(element.dataset.i18n); });
  root.querySelectorAll?.('[data-i18n-html]').forEach((element) => { element.innerHTML = t(element.dataset.i18nHtml); });
  root.querySelectorAll?.('[data-i18n-attrs]').forEach((element) => {
    for (const item of element.dataset.i18nAttrs.split(';')) {
      const [attribute, key] = item.split(':');
      if (attribute && key) element.setAttribute(attribute, t(key));
    }
  });
  return currentLocale;
}

export { TRANSLATIONS };
